import {solveOngoingActivation} from './effect-ongoing-index.js';
import {effectTagRoles,validEffectTagRequirements} from './effect-tag-requirements.js';

export function editEffectOngoing(data,requirements){if(!validEffectTagRequirements(requirements)||requirements!==undefined&&data.duration===0)throw Error('지속 효과의 태그 조건을 확인하세요.');if(requirements===undefined)delete data.ongoingRequirements;else{data.ongoingRequirements=structuredClone(requirements);data.version=Math.max(data.version,4);}}
export function bindOngoingEffect(system,effect,target,source,roles={}){if(!effect.data.ongoingRequirements)return;const objects={target:target.object,source:source.object,instigator:roles.instigator||source.object,causer:roles.causer||source.object};effect.ongoingRefs=Object.fromEntries(effectTagRoles.map(role=>[role,{id:objects[role].id,object:new WeakRef(objects[role]),generation:system.owners.get(objects[role].id)?.generation}]));system.ongoingOwners.add(target);if(!effect.ongoingRefsBound){effect.inhibited=true;system.ongoingCount++;effect.ongoingRefsBound=true;}}
const ongoingSnapshot=()=>({actors:new Map(),tags:new WeakMap()});
function resolve(system,ref,snapshot){const object=ref?.object.deref();if(!object||object.poolActive===false)return null;let current=snapshot?.actors.get(ref.id);if(!current){current={object:system.vm?.object(ref.id),generation:system.owners.get(ref.id)?.generation};snapshot?.actors.set(ref.id,current);}if(current.object!==object||ref.generation!==undefined&&current.generation!==ref.generation)return null;return object;}
function signature(system,effect,snapshot){return '['+Object.keys(effect.data.ongoingRequirements).map(role=>{const o=resolve(system,effect.ongoingRefs[role],snapshot);if(!o)return '[false]';let value=snapshot.tags.get(o);if(value===undefined){value=JSON.stringify([true,...o.tags||[]]);snapshot.tags.set(o,value);}return value;}).join(',')+']';}
export function ongoingTagsChanged(system){if(!system.ongoingCount)return false;const snapshot=ongoingSnapshot();for(const state of system.ongoingOwners)for(const effect of state.effects.values())if(effect.ongoingRefs&&effect.ongoingSignature!==signature(system,effect,snapshot))return true;return false;}
// Every conditional target participates in the same fixed point. Only the
// configured role owners can feed its tags; unrelated actors stay untouched.
export function ongoingParticipants(system,origin,related=[]){const result=new Set(),snapshot=ongoingSnapshot();const add=state=>{if(state&&system.owners.get(state.object.id)===state)result.add(state);};add(origin);for(const state of related)add(state);for(const state of system.ongoingOwners){add(state);for(const effect of state.effects.values())if(effect.ongoingRefs)for(const role of Object.keys(effect.data.ongoingRequirements)){const object=resolve(system,effect.ongoingRefs[role],snapshot),owner=object&&system.owners.get(object.id);if(owner?.object===object)add(owner);}}return result;}
// Capture the expected prior publication before mutation. First participation
// must reconcile external tag edits without mistaking this transaction for one.
export function prepareOngoingParticipants(states){for(const state of states)if(!state.ongoingPublishedTags){const tags=new Set(state.baseTags);for(const effect of state.effects.values())if(!effect.inhibited)for(const tag of effect.data.grantedTags)tags.add(tag);for(const ability of state.abilities.values())if(ability.active)for(const tag of ability.data.grantedTags)tags.add(tag);state.ongoingPublishedTags=[...tags];}}
// Resolve conditional grants together from unconditional tags. This gives
// positive dependency chains a stable least fixed point, independent of order.
// Contradictory negative cycles fail the initiating transaction atomically.
export function refreshOngoingEffects(system,participants=ongoingParticipants(system)){
 if(!system.ongoingCount)return false;const entries=[],base=new Map();for(const state of participants){
  if(state.ongoingPublishedTags){const current=new Set(state.object.tags||[]),prior=new Set(state.ongoingPublishedTags),next=new Set(state.baseTags);for(const tag of current)if(!prior.has(tag))next.add(tag);for(const tag of prior)if(!current.has(tag))next.delete(tag);state.baseTags=next;}const tags=new Set(state.baseTags);for(const ability of state.abilities.values())if(ability.active)for(const tag of ability.data.grantedTags)tags.add(tag);
  for(const effect of state.effects.values())if(effect.ongoingRefs)entries.push({state,effect});else for(const tag of effect.data.grantedTags)tags.add(tag);base.set(state.object,tags);
 }
 const roles=ongoingSnapshot(),{active}=solveOngoingActivation(entries,base,(effect,role)=>resolve(system,effect.ongoingRefs[role],roles));const tags=new Map([...base].map(([object,value])=>[object,new Set(value)]));for(let i=0;i<entries.length;i++)if(active[i])for(const tag of entries[i].effect.data.grantedTags)tags.get(entries[i].state.object).add(tag);
 let changed=false;for(let i=0;i<entries.length;i++){const{effect,state}=entries[i];if(effect.inhibited===active[i]){changed=true;state.values=null;}const inhibited=!active[i];if(effect.ongoingInitialized&&effect.inhibited!==inhibited)system.cue(state,effect.data,inhibited?'inhibit':'resume',{effect:effect.asset,handle:effect.handle,stacks:effect.stacks},effect.context);effect.inhibited=inhibited;effect.ongoingInitialized=true;}for(const[object,value]of tags){object.tags=[...value];system.owners.get(object.id).ongoingPublishedTags=[...value];}const published=ongoingSnapshot();for(const{effect}of entries)effect.ongoingSignature=signature(system,effect,published);return changed;
}
export const effectOngoingContract={assetVersion:4,field:'effect.ongoingRequirements',roles:effectTagRoles,semantics:'Current hierarchical/exact role tags, actor identity and captured owner generation. Inhibition suppresses modifiers, granted tags, immunity and periodic execution; handle, level, expiry, snapshots and phase survive. Missing configured-role lifetime inhibits; replacement IDs never rebind.',resolution:'Conditional grants resolved from unconditional base/active ability tags to a least fixed point in one transaction. Negative oscillations reject/rollback; no silent frame-to-frame toggling. Self-supplied requirements cannot bootstrap themselves.',clock:'Inhibited periodic deadlines advance without execution or catch-up damage; expiry continues. Reactivation resumes the existing phase, never executeOnApply again.',cost:'Only opt-in v4 tracks role signatures on tick. Tag/ability/effect mutations snapshot conditional targets, configured role owners, the initiating/new role owners and transitive live dependents only. Partial numeric index rebuild preserves unrelated edges. First participation reconciles external tags; all conditional grants still share one fixed point. A transaction-local exact/hierarchy count index only re-evaluates conditions whose queried tag presence changes; final tag ordering stays in original effect order. Legacy mutations retain prior affected-owner path; no asset reads, extra timers or idle numeric aggregation.',authoring:'effect.ongoing.edit and human condition controls share validation/CAS/Undo. Removal retains v4; old engines reject v4.',limits:['Per-pulse historical inputs','Network prediction','Whole conditional-world snapshot/lifetime/signature work, index construction and cycle-state scans','External direct tag edits detected on next tick']};
